// Headless Ghidra script: decompile every function of the current program.
// Usage (via tools/decompile_all.sh):
//   analyzeHeadless <proj> <name> -import <bin> -postScript ExportDecompiled.java <outdir> [names.tsv]
// Writes <outdir>/decompiled.c, functions.tsv and strings.tsv. Rows of kind "local" in
// names.tsv rename a decompiler variable first (address = function entry, dtype = old name
// as printed in decompiled.c); a type in the params column also retypes it.
//@category A2Racer

import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;

import ghidra.app.decompiler.DecompInterface;
import ghidra.app.decompiler.DecompileOptions;
import ghidra.app.decompiler.DecompileResults;
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
import ghidra.program.model.data.DataType;
import ghidra.program.model.data.PointerDataType;
import ghidra.program.model.pcode.HighFunction;
import ghidra.program.model.pcode.HighFunctionDBUtil;
import ghidra.program.model.pcode.HighSymbol;
import ghidra.program.model.symbol.SourceType;
import ghidra.program.model.listing.Data;
import ghidra.program.model.listing.DataIterator;
import ghidra.program.model.listing.Function;
import ghidra.program.model.listing.FunctionIterator;

public class ExportDecompiled extends GhidraScript {

	@Override
	protected void run() throws Exception {
		String[] args = getScriptArgs();
		File outDir = new File(args.length > 0 ? args[0] : ".");
		outDir.mkdirs();
		Map<Address, List<String[]>> renames = args.length > 1 ? readRenames(new File(args[1]))
				: new HashMap<>();
		int renamed = 0;

		DecompInterface decomp = new DecompInterface();
		decomp.setOptions(new DecompileOptions());
		decomp.toggleCCode(true);
		decomp.toggleSyntaxTree(true);
		decomp.setSimplificationStyle("decompile");
		if (!decomp.openProgram(currentProgram)) {
			throw new RuntimeException("Decompiler failed to open program: " + decomp.getLastMessage());
		}

		int ok = 0, failed = 0;
		try (PrintWriter c = new PrintWriter(new File(outDir, "decompiled.c"), "UTF-8");
				PrintWriter idx = new PrintWriter(new File(outDir, "functions.tsv"), "UTF-8")) {
			c.println("/* " + currentProgram.getName() + " — Ghidra " + getGhidraVersion()
				+ " decompilation, generated by tools/ExportDecompiled.java */");
			idx.println("address\tname\tsize\tthunk\tcallers\tcallees\tstatus\tconvention\tprototype");

			FunctionIterator it = currentProgram.getFunctionManager().getFunctions(true);
			while (it.hasNext() && !monitor.isCancelled()) {
				Function f = it.next();
				String status;
				c.println();
				c.println("/* ==== " + f.getEntryPoint() + " " + f.getName() + " ==== */");
				DecompileResults r = decomp.decompileFunction(f, 120, monitor);
				List<String[]> want = renames.get(f.getEntryPoint());
				if (want != null && r != null && r.getHighFunction() != null) {
					renamed += rename(r.getHighFunction(), want);
					r = decomp.decompileFunction(f, 120, monitor);
				}
				if (r != null && r.decompileCompleted() && r.getDecompiledFunction() != null) {
					// __watcall0..4 and _s0..3 only differ in which registers carry arguments and
					// survive a call; print one name.
					c.print(r.getDecompiledFunction().getC().replaceAll("\\b__watcall(_s)?[0-4]\\b", "__watcall")
						.replace("__watcall_varargs", "__cdecl"));
					status = "ok";
					ok++;
				}
				else {
					String msg = r == null ? "no result" : r.getErrorMessage();
					c.println("/* decompile failed: " + msg.replace("*/", "* /").trim() + " */");
					status = "failed";
					failed++;
				}
				idx.println(f.getEntryPoint() + "\t" + f.getName() + "\t" + f.getBody().getNumAddresses()
					+ "\t" + f.isThunk() + "\t" + f.getCallingFunctions(monitor).size() + "\t"
					+ f.getCalledFunctions(monitor).size() + "\t" + status + "\t"
					+ f.getCallingConventionName() + "\t"
					+ f.getSignature().getPrototypeString(true).replaceAll("\\b__watcall[0-4]\\b", "__watcall")
						.replace("__watcall_varargs", "__cdecl"));
			}
		}
		finally {
			decomp.dispose();
		}

		try (PrintWriter s = new PrintWriter(new File(outDir, "strings.tsv"), "UTF-8")) {
			s.println("address\ttype\tvalue");
			DataIterator di = currentProgram.getListing().getDefinedData(true);
			while (di.hasNext()) {
				Data d = di.next();
				if (d.hasStringValue()) {
					String v = String.valueOf(d.getValue()).replace("\\", "\\\\").replace("\t", "\\t")
						.replace("\r", "\\r").replace("\n", "\\n");
					s.println(d.getAddress() + "\t" + d.getDataType().getName() + "\t" + v);
				}
			}
		}
		println("ExportDecompiled: " + ok + " functions decompiled, " + failed + " failed, " +
			renamed + " variables renamed -> " + outDir);
	}

	private Map<Address, List<String[]>> readRenames(File tsv) throws Exception {
		Map<Address, List<String[]>> m = new HashMap<>();
		try (BufferedReader r = new BufferedReader(new FileReader(tsv))) {
			String line;
			while ((line = r.readLine()) != null) {
				String[] c = line.split("\t", -1);
				if (c.length > 6 && c[1].equals("local")) {
					m.computeIfAbsent(toAddr(c[0]), k -> new ArrayList<>())
							.add(new String[] { c[6], c[2], c[5] });
				}
			}
		}
		return m;
	}

	/** Renames decompiler variables (old -> new); returns how many were applied. */
	private int rename(HighFunction hf, List<String[]> want) {
		int n = 0;
		for (String[] w : want) {
			Iterator<HighSymbol> it = hf.getLocalSymbolMap().getSymbols();
			while (it.hasNext()) {
				HighSymbol sym = it.next();
				if (sym.getName().equals(w[0])) {
					try {
						DataType dt = w.length > 2 && !w[2].isEmpty() ? resolveType(w[2]) : null;
						HighFunctionDBUtil.updateDBVariable(sym, w[1], dt, SourceType.USER_DEFINED);
						n++;
					}
					catch (Exception e) {
						printerr("ExportDecompiled: " + hf.getFunction().getName() + ": cannot rename " +
							w[0] + " -> " + w[1] + ": " + e.getMessage());
					}
					break;
				}
			}
		}
		return n;
	}

	/** "button_t*" and the like: a named type from the program plus pointer levels. */
	private DataType resolveType(String t) {
		int depth = 0;
		while (t.endsWith("*")) {
			depth++;
			t = t.substring(0, t.length() - 1);
		}
		List<DataType> found = new ArrayList<>();
		currentProgram.getDataTypeManager().findDataTypes(t, found);
		if (found.isEmpty()) {
			printerr("ExportDecompiled: unknown type " + t);
			return null;
		}
		DataType dt = found.get(0);
		for (int i = 0; i < depth; i++) {
			dt = new PointerDataType(dt, currentProgram.getDataTypeManager());
		}
		return dt;
	}
}
